sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }
	var parts;
    // newValue vem no formato dd/MM/yyyy no portal
	if (newValue.includes('/')){parts = newValue.split('/');}
    if (newValue.includes('-')){parts = newValue.split('-');}

	var day = parseInt(parts[0], 10);
    var month = parseInt(parts[1], 10) - 1; 
    var year = parseInt(parts[2], 10);

    var inputDate = new Date(year, month, day);

    var today = new Date();
    today.setHours(0, 0, 0, 0);

    if (inputDate.getTime() < today.getTime()) {
		g_form.clearValue('begin_date');
        g_form.showFieldMsg('begin_date','The start date must be today or later.', 'error');
    }

	g_form.clearValue('end_date');
}
